def user_node(state): return {'count': state['count'] + 1}

def channel_write(ret_dict, out_buf):
    for k, v in ret_dict.items(): out_buf.append((k, v))
    out_buf.append(('branch:to:next', '__done__'))

buf = []
channel_write(user_node({'count': 0}), buf)
print('Pipeline emitted:', buf)
